import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { DossierService } from '../../core/services/dossier.service';
import { ProprietaireService } from '../../core/services/proprietaire.service';
import { Proprietaire } from '../../core/models/models';

@Component({
  selector: 'app-dossier-form',
  templateUrl: './dossier-form.component.html'
})
export class DossierFormComponent implements OnInit {
  form: FormGroup;
  loading = false;
  isEdit = false;
  id?: number;
  error = '';
  proprietaires: Proprietaire[] = [];

  constructor(
    private fb: FormBuilder,
    private service: DossierService,
    private proprietaireService: ProprietaireService,
    private route: ActivatedRoute,
    private router: Router
  ) {
    this.form = this.fb.group({
      libelle: ['', Validators.required],
      duree: [1, [Validators.required, Validators.min(1)]],
      budget: [0, [Validators.required, Validators.min(0.01)]],
      description: [''],
      proprietaireId: [null, Validators.required]
    });
  }

  ngOnInit(): void {
    this.proprietaireService.getAll(0, 200).subscribe({
      next: (p) => this.proprietaires = p.content
    });

    const preselected = this.route.snapshot.queryParamMap.get('proprietaireId');
    if (preselected) {
      this.form.patchValue({ proprietaireId: +preselected });
    }

    const idParam = this.route.snapshot.paramMap.get('id');
    if (idParam && idParam !== 'nouveau') {
      this.isEdit = true;
      this.id = +idParam;
      this.service.getById(this.id).subscribe({
        next: (d) => {
          this.form.patchValue({
            libelle: d.libelle,
            duree: d.duree,
            budget: d.budget,
            description: d.description,
            proprietaireId: d.proprietaire?.id
          });
        },
        error: () => this.router.navigate(['/dossiers'])
      });
    }
  }

  onSubmit(): void {
    if (this.form.invalid) return;
    this.loading = true;
    this.error = '';
    const data = { ...this.form.value };
    const obs = this.isEdit
      ? this.service.update(this.id!, data)
      : this.service.create(data);

    obs.subscribe({
      next: () => this.router.navigate(['/dossiers']),
      error: (err) => {
        this.loading = false;
        this.error = err.error?.message || 'Erreur lors de l\'enregistrement';
      }
    });
  }
}
<div class="mb-4">
  <h1 class="page-title">{{ isEdit ? 'Modifier' : 'Ajouter' }} un dossier de soins</h1>
  <p class="page-subtitle">
    <a routerLink="/dossiers" class="text-muted">&larr; Retour à la liste</a>
  </p>
</div>

<div class="card" style="max-width:640px;">
  <div class="card-body">
    <div *ngIf="error" class="alert alert-danger">{{ error }}</div>
    <form [formGroup]="form" (ngSubmit)="onSubmit()">
      <div class="mb-3">
        <label class="form-label">Libellé *</label>
        <input type="text" class="form-control" formControlName="libelle"
               placeholder="ex. Vaccination annuelle de Rex">
      </div>
      <div class="mb-3">
        <label class="form-label">Propriétaire *</label>
        <select class="form-select" formControlName="proprietaireId">
          <option [ngValue]="null" disabled>Sélectionner un propriétaire</option>
          <option *ngFor="let p of proprietaires" [ngValue]="p.id">{{ p.nom }}</option>
        </select>
      </div>
      <div class="row">
        <div class="col-md-6 mb-3">
          <label class="form-label">Durée (jours) *</label>
          <input type="number" class="form-control" formControlName="duree" min="1">
        </div>
        <div class="col-md-6 mb-3">
          <label class="form-label">Budget (TND) *</label>
          <input type="number" class="form-control" formControlName="budget" min="0.01" step="0.01">
        </div>
      </div>
      <div class="mb-3">
        <label class="form-label">Description</label>
        <textarea class="form-control" formControlName="description" rows="3"
                  placeholder="Espèce, race, symptômes, remarques..."></textarea>
      </div>
      <div class="d-flex gap-2">
        <button type="submit" class="btn btn-primary" [disabled]="loading || form.invalid">
          <span *ngIf="loading" class="spinner-border spinner-border-sm me-1"></span>
          {{ isEdit ? 'Mettre à jour' : 'Créer' }}
        </button>
        <a routerLink="/dossiers" class="btn btn-outline-secondary">Annuler</a>
      </div>
    </form>
  </div>
</div>
